5	/**
6	 * A class representing shared characteristics of consumers.
7	 *
8	 * @version 18.02.22 (DD:MM:YY)
9	 */
10	public abstract class Consumer extends Actor
11	{
12	    // Properties shared between all consumers:
13	    private static final int STARTING_SUSTENANCE_LEVEL = 20;
14	    private static final double NEW_DISEASE = 0.0005;
15	    private static final double NIGHT_PREY_MISS_PROBABILITY = 0.5;
16	    private static Random rand = Randomizer.getRandom();
17	
18	    // Properties unique to this consumer:
19	    private int breedingAge;
20	    private int sustenanceLevel;
21	    private int maxSustenanceLevel;
22	    private List<Class<?>> prey;
23	    private Disease disease;
24	    private boolean ifCarcass;
25	    private Carcass newCarcass;
26	    private boolean canEatCarcass;
27	    private boolean primaryConsumer;
28	    
29	    /**
30	     * Create a new consumer at a location in the field.
31	     * 
32	     * @param field               The field currently occupied.
33	     * @param location            The location within the field.
34	     * @param consumptionWorth    The worth of the consumer if consumed.
35	     * @param breedingProbability The liklihood of the consumer breeding.
36	     * @param maxBirthsAtOnce     The max number of births for the consumer.
37	     * @param maxAge              The age to which this consumer can live.
38	     * @param breedingAge         The age at which this consumer can start to breed.
39	     */
40	    public Consumer(Field field, Location location, List<Class<?>> prey, int consumptionWorth,
41	                    double breedingProbability, int maxBirthsAtOnce, int maxAge, int breedingAge,int maxSustenanceLevel,boolean canEatCarcass,boolean primaryConsumer)
42	    {
43	        super(field, location, consumptionWorth, breedingProbability, maxBirthsAtOnce,maxSustenanceLevel,maxAge);
44	        this.canEatCarcass = canEatCarcass;
45	        this.prey = prey;
46	        this.maxAge = maxAge;
47	        this.breedingAge = breedingAge;
48	        this.primaryConsumer = primaryConsumer;
49	        sustenanceLevel = 30;
50	    }
51	    
52	    /**
53	     * Make this consumer act - that is: make it do
54	     * whatever it wants/needs to do.
55	     * 
56	     * @param newConsumers A list to receive newly born consumers.
57	     */
58	    public void act(List<Actor> newConsumers)
59	    {   
60	        incrementAge();
61	        incrementHunger();
62	        if (getIsAlive())
63	        {
64	            giveBirth(newConsumers);
65	            boolean wasPossibleToMove = huntForFood();
66	            if(ifCarcass)
67	            {
68	                newConsumers.add(newCarcass);
69	                ifCarcass = false;
70	                newCarcass = null;
71	            }
72	            if(hasDisease())
73	            {                                                                                   
74	                diseaseEffect();
75	            }
76	            if (!wasPossibleToMove)
77	            {
78	                setDead();
79	            }
80	        }
81	    }
82	    /**
83	     * Returns true if this consumer is diseased else return false.
84	     * @return boolean
85	     */
86	    private boolean hasDisease()
87	    {
88	        return this.disease != null;
89	    }
90	    /**
91	     * Returns a new Disease.
92	     * @return diseae
93	     */
94	    private Disease giveDisease()
95	    {
96	        return new Disease();
97	    }
98	    /**
99	     * If the animal is diseased then evolve the disease.
100	     */
101	    private void diseaseEffect()
102	    {
103	        if(hasDisease())
104	        {
105	            disease.decrementStepsBeforeDeath();
106	            spreadDisease();
107	            checkForFatalDisease();
108	            incrementHunger();
109	        }
110	    }
111	    /**
112	     * Check if the disease is fatal to the animal.
113	     */
114	    private void checkForFatalDisease()
115	    {
116	        if(hasDisease() && disease.diseaseFinished())
117	        {   
118	            if(disease.isFatal())
119	            {
120	                setDead();
121	            }
122	            disease = null;
123	        }
124	    }
125	    /**
126	     * Spread the disease to different animals of the same species.
127	     */
128	    private void spreadDisease()
129	    {
130	            Field field = getField();
131	            List<Location> adjacent = field.adjacentLocations(getLocation());
132	            Iterator<Location> it = adjacent.iterator();
133	            while(it.hasNext())
134	
135	            {
136	                Location loc = it.next();
137	                Object animal = field.getObjectAt(loc);
138	                Actor consumer = (Actor) animal;
139	                if(consumer != null && consumer.getClass() == this.getClass() && this.hasDisease())
140	                {
141	                    ((Consumer) consumer).disease = giveDisease();
142	                }
143	            }
144	    }
145	    /**
146	     * Hunt for food by moving toward it.
147	     */
148	    private boolean huntForFood()
149	    {
150	        // Move towards a source of food if found:
151	        Location newLocation = findFood();
152	        
153	        if (newLocation == null)
154	        { 
155	            // No food found - try to move to a free location:
156	            newLocation = getField().freeAdjacentLocation(getLocation());
157	        }
158	        
159	        // See if it was possible to move.
160	        if (newLocation != null) setLocation(newLocation);
161	        
162	        return newLocation != null;
163	    }
164	    
165	    /**
166	     * Set the starting age of the consumer, dependent on whether a random
167	     * age has been selected.
168	     * 
169	     * @param randomAge If true, the age is random, otherwise it's 0.
170	     */
171	    protected void setStartingAge(boolean randomAge)
172	    {
173	        if (randomAge) currentAge = rand.nextInt(maxAge) ;
174	        else           currentAge = 0;
175	    }
176	    
